from common import *
def project(p):
 return {'schema_version':'pilot-graph/2','basis_sha256':p['basis']['sha256'],'status':'validation_only_not_published','nodes':[{'id':x['id'],'type':x['type'],'source_refs':x['source_refs']} for x in p['entities']], 'edges':[{'id':x['id'],'kind':'fact_attachment','target':x['target_ref'],'claim_refs':x['claim_refs'],'scope_ref':x['scope_ref'],'application_state':x['application_state'],'resolution_ref':x['resolution_ref'],'unknown_reasons':x['unknown_reasons']} for x in p['attachments']], 'identity_lookup':[{'mapping_ref':m['id'],'selected_refs':m['selected_refs'],'source_refs':m['source_refs'],'clinical_application':'unknown'} for m in p['mappings'] if m['purpose']=='identity' and m['state']=='exact'], 'source_fact_lookup':[{'claim_ref':c['id'],'predicate':c['predicate'],'scope_ref':c['scope_ref'],'raw_value':c['raw_value'],'source_refs':c['source_refs'],'clinical_application':'unknown'} for c in p['claims']], 'facts':p['claims'],'relation_records':p['relation_claims'],'mapping_records':p['mappings'],'scope_records':p['scopes'],'legacy_aliases':p['legacy_aliases'],'notes':p['notes'],'resolutions':p['resolutions'],'decisions':p['decisions'],'source_records':p['source_records'],'snapshots':p['snapshots'],'withheld_procedure_edges':[{'relation_ref':x['id'],'reason':'single attribute' if x['arity']==1 else 'source relation retained; mappings and/or application unreviewed; existing pairs are evidence','source_record_ref':x['source_record_ref']} for x in p['relation_claims']]}
